"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[95],{417:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>hw-02-erm-least-squares</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="домашняя-работа-2-как-на-самом-деле-решают-мнк">Домашняя работа\n2. Как на самом деле решают МНК</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>К семинару</td>\n<td>занятие 2 — Эмпирический риск и метод наименьших квадратов</td>\n</tr>\n<tr>\n<td>Опора</td>\n<td>материал семинара 2 и лекций до него</td>\n</tr>\n<tr>\n<td>Ожидаемое время</td>\n<td>3–4 часа</td>\n</tr>\n</tbody>\n</table>\n<p>На занятии мы вызывали <code>np.linalg.lstsq</code> и\n<code>LinearRegression</code>, не заглядывая внутрь. Дома разберёмся,\nчто там происходит: проверим формулы матричного дифференцирования\nчисленно, реализуем пять способов решить одну и ту же задачу и увидим,\nгде четыре из них ломаются. В конце — связь между предположением о шуме\nи выбором функции потерь.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук, в котором:</p>\n<ol>\n<li>выполнены все ячейки с <code># TODO</code>, код исполняется сверху\nвниз без ошибок в свежем ядре (Kernel → Restart &amp; Run All);</li>\n<li>под каждым заданием заполнена ячейка <strong>Вывод</strong> — своими\nсловами;</li>\n<li>графики подписаны: заголовок, оси, легенда;</li>\n<li>вариант ваш собственный (ячейка ниже).</li>\n</ol>\n<blockquote>\n<p>Списывание видно сразу: у каждого студента свой датасет и свой набор\nметодов.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span></code></pre></div>\n</div>\n<div id="cell002" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell003" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">2</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell004" class="cell markdown">\n<hr />\n<h1 id="задача-1-матричное-дифференцирование-проверка-конечными-разностями">Задача\n1. Матричное дифференцирование: проверка конечными разностями</h1>\n<p>В §6 лекции 1 выведены два тождества:</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>w</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>a</mi><mi>𝖳</mi></msup><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>a</mi><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>∇</mi><mi>w</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><mi>A</mi><mi>w</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo>+</mo><msup><mi>A</mi><mi>𝖳</mi></msup><mo stretchy="false" form="postfix">)</mo><mi>w</mi><mo>,</mo></mrow><annotation encoding="application/x-tex">\n\\nabla_w (a^{\\mathsf T} w) = a,\n\\qquad\n\\nabla_w (w^{\\mathsf T} A w) = (A + A^{\\mathsf T}) w,\n</annotation></semantics></math></p>\n<p>и из них — градиент квадрата нормы невязки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>∇</mi><mi>θ</mi></msub><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mo>=</mo><mn>2</mn><msup><mi>X</mi><mi>𝖳</mi></msup><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\nabla_\\theta\\|X\\theta - y\\|^2 = 2X^{\\mathsf T}(X\\theta - y)</annotation></semantics></math>.</p>\n<p>Проверить формулу можно, не доказывая её заново: сравнить с\nцентральной конечной разностью</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mfrac><mrow><mi>∂</mi><mi>f</mi></mrow><mrow><mi>∂</mi><msub><mi>w</mi><mi>k</mi></msub></mrow></mfrac><mo>≈</mo><mfrac><mrow><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo>+</mo><mi>h</mi><msub><mi>e</mi><mi>k</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>w</mi><mo>−</mo><mi>h</mi><msub><mi>e</mi><mi>k</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><mrow><mn>2</mn><mi>h</mi></mrow></mfrac><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\frac{\\partial f}{\\partial w_k} \\approx \\frac{f(w + he_k) - f(w - he_k)}{2h}.\n</annotation></semantics></math></p>\n<p>Приём стоит запомнить: при реализации любого градиента «с нуля» (а\nэто будет в занятиях 3 и 4) такая проверка за пять строк ловит ошибку в\nвыкладке.</p>\n</div>\n<div id="cell005" class="cell markdown">\n<h3 id="задание-11-функция-numeric_grad">Задание 1.1. Функция\n<code>numeric_grad</code></h3>\n</div>\n<div id="cell006" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> numeric_grad(f, w, h<span class="op">=</span><span class="fl">1e-6</span>):</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Градиент центральными разностями.</span></span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a><span class="co">    Для каждой координаты k: сдвинуть w на +h и -h по этой координате,</span></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="co">    взять разность значенийف и поделить на 2h.</span></span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>    <span class="co"># </span><span class="al">TODO</span></span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span></code></pre></div>\n</div>\n<div id="cell007" class="cell markdown">\n<h3 id="задание-12-проверка-трёх-формул">Задание 1.2. Проверка трёх\nформул</h3>\n<p>Проверьте все три тождества. Матрицу\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>\nберите <strong>несимметричной</strong>: для симметричной формула\nвырождается в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn><mi>A</mi><mi>w</mi></mrow><annotation encoding="application/x-tex">2Aw</annotation></semantics></math>,\nи ошибку «забыл транспонировать» не видно.</p>\n</div>\n<div id="cell008" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">6</span></span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>w0 <span class="op">=</span> rng.normal(size<span class="op">=</span>n)</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>a <span class="op">=</span> rng.normal(size<span class="op">=</span>n)</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a>A <span class="op">=</span> rng.normal(size<span class="op">=</span>(n, n))                <span class="co"># намеренно несимметричная</span></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a>X_chk <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">40</span>, n))</span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a>y_chk <span class="op">=</span> rng.normal(size<span class="op">=</span><span class="dv">40</span>)</span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: проверьте три формулы, сравнив аналитический градиент с численным:</span></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = a^T w          -&gt; a</span></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = w^T A w        -&gt; (A + A^T) w</span></span>\n<span id="cb4-11"><a href="#cb4-11" aria-hidden="true" tabindex="-1"></a><span class="co">#   f(w) = ||X w - y||^2  -&gt; 2 X^T (X w - y)</span></span></code></pre></div>\n</div>\n<div id="cell009" class="cell markdown">\n<h3 id="задание-13-выбор-шага-h">Задание 1.3. Выбор шага\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>h</mi><annotation encoding="application/x-tex">h</annotation></semantics></math></h3>\n<p>Постройте зависимость ошибки проверки от\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>h</mi><annotation encoding="application/x-tex">h</annotation></semantics></math>\nв двойном логарифмическом масштабе для\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>h</mi><annotation encoding="application/x-tex">h</annotation></semantics></math>\nот\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mn>10</mn><mrow><mi>−</mi><mn>1</mn></mrow></msup><annotation encoding="application/x-tex">10^{-1}</annotation></semantics></math>\nдо\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mn>10</mn><mrow><mi>−</mi><mn>12</mn></mrow></msup><annotation encoding="application/x-tex">10^{-12}</annotation></semantics></math>.\nУ кривой должен быть минимум — найдите его и объясните обе ветви.</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для h из np.logspace(-1, -12, 40) посчитайте максимальную ошибку</span></span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       численного градиента для f(w) = ||Xw - y||^2 и постройте график</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       в двойном логарифмическом масштабе. Отметьте минимум.</span></span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Почему ошибка растёт и при слишком большом, и\nпри слишком малом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>h</mi><annotation encoding="application/x-tex">h</annotation></semantics></math>?\nГде примерно оптимум и почему именно там?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell012" class="cell markdown">\n<hr />\n<h1 id="задача-2-пять-способов-решить-мнк">Задача 2. Пять способов\nрешить МНК</h1>\n<p>На занятии мы пользовались двумя (<code>solve</code> и\n<code>lstsq</code>) и мельком отметили, что явное обращение матрицы —\nплохая идея. Теперь измерим, насколько плохая.</p>\n<p>Реализуйте пять решателей одной и той же задачи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>θ</mi></msub><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\min_\\theta\\|X\\theta - y\\|^2</annotation></semantics></math>:</p>\n<ol>\n<li><code>fit_inv</code> — буквально по формуле теоремы 1.20, через\n<code>np.linalg.inv</code>;</li>\n<li><code>fit_solve</code> — решение нормальных уравнений без\nобращения;</li>\n<li><code>fit_qr</code> — через QR-разложение:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>X</mi><mo>=</mo><mi>Q</mi><mi>R</mi></mrow><annotation encoding="application/x-tex">X = QR</annotation></semantics></math>,\nзатем\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mi>θ</mi><mo>=</mo><msup><mi>Q</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">R\\theta = Q^{\\mathsf T}y</annotation></semantics></math>;</li>\n<li><code>fit_lstsq</code> — <code>np.linalg.lstsq</code>;</li>\n<li><code>fit_svd</code> — SVD вручную:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>θ</mi><mo>=</mo><mi>V</mi><msup><mi mathvariant="normal">Σ</mi><mo>+</mo></msup><msup><mi>U</mi><mi>𝖳</mi></msup><mi>y</mi></mrow><annotation encoding="application/x-tex">\\theta = V\\Sigma^{+}U^{\\mathsf T}y</annotation></semantics></math>\nс отсечением малых сингулярных чисел.</li>\n</ol>\n</div>\n<div id="cell013" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> linalg</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_inv(X, y):</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;(X^T X)^{-1} X^T y -- буквально по формуле теоремы 1.20.&quot;&quot;&quot;</span></span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_solve(X, y):</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Решение нормальных уравнений X^T X theta = X^T y без обращения.&quot;&quot;&quot;</span></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_qr(X, y):</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;X = QR (linalg.qr, mode=&#39;economic&#39;), затем solve_triangular(R, Q^T y).&quot;&quot;&quot;</span></span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-18"><a href="#cb6-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-19"><a href="#cb6-19" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_lstsq(X, y):</span>\n<span id="cb6-20"><a href="#cb6-20" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-21"><a href="#cb6-21" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-22"><a href="#cb6-22" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-23"><a href="#cb6-23" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> fit_svd(X, y, tol<span class="op">=</span><span class="fl">1e-12</span>):</span>\n<span id="cb6-24"><a href="#cb6-24" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;theta = V Sigma^+ U^T y; сингулярные числа меньше tol * s.max() обнулить.&quot;&quot;&quot;</span></span>\n<span id="cb6-25"><a href="#cb6-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb6-26"><a href="#cb6-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-27"><a href="#cb6-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-28"><a href="#cb6-28" aria-hidden="true" tabindex="-1"></a>SOLVERS <span class="op">=</span> {<span class="st">&quot;inv&quot;</span>: fit_inv, <span class="st">&quot;solve&quot;</span>: fit_solve, <span class="st">&quot;QR&quot;</span>: fit_qr,</span>\n<span id="cb6-29"><a href="#cb6-29" aria-hidden="true" tabindex="-1"></a>           <span class="st">&quot;lstsq&quot;</span>: fit_lstsq, <span class="st">&quot;SVD вручную&quot;</span>: fit_svd}</span></code></pre></div>\n</div>\n<div id="cell014" class="cell markdown">\n<h3 id="задание-21-сверка-на-примере-из-конспекта">Задание 2.1. Сверка\nна примере из конспекта</h3>\n<p>Все пять способов обязаны дать\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>θ</mi><mo>*</mo></msup><mo>≈</mo><mo stretchy="false" form="prefix">(</mo><mn>2.201</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.893</mn><mo>,</mo><mspace width="0.222em"></mspace><mn>0.114</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\theta^*\\approx(2.201,\\ 0.893,\\ 0.114)</annotation></semantics></math>\nна выборке из восьми кошек (пример 1.21).</p>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>f1 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">1</span>, <span class="dv">4</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>f2 <span class="op">=</span> np.array([<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">5</span>, <span class="dv">7</span>, <span class="dv">10</span>, <span class="dv">2</span>, <span class="dv">8</span>], dtype<span class="op">=</span><span class="bu">float</span>)</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a>y_cats <span class="op">=</span> np.array([<span class="fl">3.0</span>, <span class="fl">4.2</span>, <span class="fl">4.5</span>, <span class="fl">5.5</span>, <span class="fl">4.8</span>, <span class="fl">6.0</span>, <span class="fl">3.4</span>, <span class="fl">6.6</span>])</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>X_cats <span class="op">=</span> np.column_stack([np.ones(<span class="dv">8</span>), f1, f2])</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: примените все пять решателей и сведите в таблицу вместе с</span></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       отличием от theta* = (2.201, 0.893, 0.114) из конспекта.</span></span></code></pre></div>\n</div>\n<div id="cell016" class="cell markdown">\n<h3 id="задание-22-где-они-ломаются">Задание 2.2. Где они ломаются</h3>\n<p>Матрица Вандермонда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>X</mi><mrow><mi>i</mi><mi>j</mi></mrow></msub><mo>=</mo><msubsup><mi>t</mi><mi>i</mi><mrow><mspace width="0.167em"></mspace><mi>j</mi><mo>−</mo><mn>1</mn></mrow></msubsup></mrow><annotation encoding="application/x-tex">X_{ij} = t_i^{\\,j-1}</annotation></semantics></math>\nпечально известна обусловленностью. Возьмите\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>\nравномерно на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">[</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">[0,1]</annotation></semantics></math>,\nзадайте <strong>точный</strong> ответ\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msub><mi>θ</mi><mtext mathvariant="normal">истина</mtext></msub><annotation encoding="application/x-tex">\\theta_{\\text{истина}}</annotation></semantics></math>\nи постройте\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>=</mo><mi>X</mi><msub><mi>θ</mi><mtext mathvariant="normal">истина</mtext></msub></mrow><annotation encoding="application/x-tex">y = X\\theta_{\\text{истина}}</annotation></semantics></math>\n<strong>без шума</strong>: тогда любая ошибка — чисто\nвычислительная.</p>\n<p>Постройте график\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="postfix">∥</mo><mover><mi>θ</mi><mo accent="true">̂</mo></mover><mo>−</mo><msub><mi>θ</mi><mtext mathvariant="normal">истина</mtext></msub><mo stretchy="false" form="postfix">∥</mo></mrow><annotation encoding="application/x-tex">\\|\\hat\\theta - \\theta_{\\text{истина}}\\|</annotation></semantics></math>\nот числа столбцов для всех пяти методов и рядом — рост\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X)</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X)^2</annotation></semantics></math>.</p>\n</div>\n<div id="cell017" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a>t <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">120</span>)</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>degrees <span class="op">=</span> <span class="bu">range</span>(<span class="dv">2</span>, <span class="dv">15</span>)</span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждого числа столбцов p:</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="co">#   X_v = np.vander(t, p, increasing=True); theta_true случайный;</span></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a><span class="co">#   y_v = X_v @ theta_true (БЕЗ шума);</span></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   решите всеми пятью способами, запомните ||theta_hat - theta_true||</span></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a><span class="co">#   и cond(X_v).</span></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: два графика в логарифмическом масштабе: ошибки методов и</span></span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       cond(X), cond(X)^2, уровень 1/eps.</span></span></code></pre></div>\n</div>\n<div id="cell018" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> С какого числа обусловленности\n<code>inv</code> и <code>solve</code> дают бессмысленный ответ? Почему\nQR и SVD держатся дольше?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell019" class="cell markdown">\n<hr />\n<h1 id="задача-3-шум-определяет-функцию-потерь">Задача 3. Шум определяет\nфункцию потерь</h1>\n<p>Утверждение 1.15 связывает ERM и максимум правдоподобия: если\nположить\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℒ</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>θ</mi></msub><mo>,</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathcal L(a_\\theta, x, y) = -\\ln\\varphi(x,y,\\theta)</annotation></semantics></math>,\nпринципы совпадают. Для гауссовского шума (пример 1.22)</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo>=</mo><mi>C</mi><mo>+</mo><mfrac><mn>1</mn><mrow><mn>2</mn><msup><mi>σ</mi><mn>2</mn></msup></mrow></mfrac><mo stretchy="false" form="prefix">(</mo><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mspace width="0.278em"></mspace><mo>⇒</mo><mspace width="0.278em"></mspace><msub><mi>θ</mi><mrow><mi mathvariant="normal">M</mi><mi mathvariant="normal">L</mi></mrow></msub><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><munder><mi>min</mi><mi>θ</mi></munder><mo stretchy="false" form="postfix">∥</mo><mi>X</mi><mi>θ</mi><mo>−</mo><mi>y</mi><msup><mo stretchy="false" form="postfix">∥</mo><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">\n-\\ln\\varphi = C + \\frac{1}{2\\sigma^2}(g(x,\\theta) - y)^2\n\\;\\Longrightarrow\\;\n\\theta_{\\mathrm{ML}} = \\arg\\min_\\theta\\|X\\theta - y\\|^2 .\n</annotation></semantics></math></p>\n<p>А если шум лапласовский,\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo stretchy="false" form="prefix">(</mo><mi>ε</mi><mo stretchy="false" form="postfix">)</mo><mo>∝</mo><msup><mi>e</mi><mrow><mi>−</mi><mo stretchy="false" form="prefix">|</mo><mi>ε</mi><mo stretchy="false" form="prefix">|</mo><mi>/</mi><mi>b</mi></mrow></msup></mrow><annotation encoding="application/x-tex">p(\\varepsilon)\\propto e^{-|\\varepsilon|/b}</annotation></semantics></math>,\nто\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>φ</mi><mo>=</mo><mi>C</mi><mo>+</mo><mo stretchy="false" form="prefix">|</mo><mi>g</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>θ</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>y</mi><mo stretchy="false" form="prefix">|</mo><mi>/</mi><mi>b</mi></mrow><annotation encoding="application/x-tex">-\\ln\\varphi = C + |g(x,\\theta) - y|/b</annotation></semantics></math>\n— и получается <strong>абсолютная</strong> потеря.</p>\n<p>Проверим оба утверждения и посмотрим, что будет при выбросах.</p>\n</div>\n<div id="cell020" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> neg_loglik_gauss(theta, X, y, sigma<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;-ln L для модели y = X theta + N(0, sigma^2), без не зависящих от theta слагаемых.&quot;&quot;&quot;</span></span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> neg_loglik_laplace(theta, X, y, b<span class="op">=</span><span class="fl">1.0</span>):</span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;-ln L для модели y = X theta + Laplace(0, b).&quot;&quot;&quot;</span></span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-13"><a href="#cb9-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-14"><a href="#cb9-14" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">120</span></span>\n<span id="cb9-15"><a href="#cb9-15" aria-hidden="true" tabindex="-1"></a>x <span class="op">=</span> np.sort(rng.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n))</span>\n<span id="cb9-16"><a href="#cb9-16" aria-hidden="true" tabindex="-1"></a>X_lin <span class="op">=</span> np.column_stack([np.ones(n), x])</span>\n<span id="cb9-17"><a href="#cb9-17" aria-hidden="true" tabindex="-1"></a>THETA_TRUE <span class="op">=</span> np.array([<span class="fl">2.0</span>, <span class="fl">3.0</span>])</span>\n<span id="cb9-18"><a href="#cb9-18" aria-hidden="true" tabindex="-1"></a>y_clean <span class="op">=</span> X_lin <span class="op">@</span> THETA_TRUE <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.3</span>, n)</span>\n<span id="cb9-19"><a href="#cb9-19" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-20"><a href="#cb9-20" aria-hidden="true" tabindex="-1"></a>y_dirty <span class="op">=</span> y_clean.copy()</span>\n<span id="cb9-21"><a href="#cb9-21" aria-hidden="true" tabindex="-1"></a>outliers <span class="op">=</span> rng.choice(n, size<span class="op">=</span><span class="dv">6</span>, replace<span class="op">=</span><span class="va">False</span>)</span>\n<span id="cb9-22"><a href="#cb9-22" aria-hidden="true" tabindex="-1"></a>y_dirty[outliers] <span class="op">+=</span> rng.choice([<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>], <span class="dv">6</span>) <span class="op">*</span> rng.uniform(<span class="dv">6</span>, <span class="dv">12</span>, <span class="dv">6</span>)</span></code></pre></div>\n</div>\n<div id="cell021" class="cell markdown">\n<h3 id="задание-31-ммп-против-мнк">Задание 3.1. ММП против МНК</h3>\n<p>Для чистых и для испорченных данных найдите\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>θ</mi><annotation encoding="application/x-tex">\\theta</annotation></semantics></math>\nтремя способами: МНК, минимизацией гауссовского\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>−</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>L</mi></mrow><annotation encoding="application/x-tex">-\\ln L</annotation></semantics></math>\nи минимизацией лапласовского. Лапласовская функция негладкая —\nиспользуйте <code>method=&quot;Nelder-Mead&quot;</code>.</p>\n</div>\n<div id="cell022" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для y_clean и y_dirty найдите theta тремя способами</span></span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       (lstsq, минимизация neg_loglik_gauss, минимизация neg_loglik_laplace)</span></span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       и сведите в таблицу. Сравните с THETA_TRUE.</span></span></code></pre></div>\n</div>\n<div id="cell023" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: нарисуйте данные с выбросами, обе подогнанные прямые</span></span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       (гауссовскую и лапласовскую) и истинную зависимость.</span></span></code></pre></div>\n</div>\n<div id="cell024" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпали ли ММП при гауссовском шуме и МНК?\nКакая прямая устояла против выбросов и почему? Свяжите ответ с частью 1\nсеминара.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell025" class="cell markdown">\n<h2 id="итоги-домашней-работы">Итоги домашней работы</h2>\n<p>Кратко ответьте на вопросы:</p>\n<ol>\n<li>Вы решаете МНК на данных, где один признак измерен в рублях, а\nдругой — в долях единицы. Как это скажется на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">c</mi><mi mathvariant="normal">o</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">d</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{cond}(X)</annotation></semantics></math>\nи что стоит сделать до обучения?</li>\n<li>В каком случае вы предпочтёте абсолютную потерю квадратичной, даже\nзная, что шум гауссовский?</li>\n</ol>\n<hr />\n<p>Проверьте перед сдачей: Kernel → Restart &amp; Run All проходит без\nошибок, все ячейки <strong>Вывод</strong> заполнены, графики\nподписаны.</p>\n</div>\n</body>\n</html>\n'}}]);